import sys, zlib, re

def extract(path):
    d = open(path, 'rb').read()
    chunks = []
    for m in re.finditer(rb'stream\r?\n', d):
        s = m.end()
        e = d.find(b'endstream', s)
        if e < 0: continue
        try:
            t = zlib.decompress(d[s:e])
        except Exception:
            continue
        chunks.append(t)
    lines = []
    for t in chunks:
        txt = t.decode('latin-1')
        # find text-showing ops, in order
        for m in re.finditer(r'\[(?P<arr>[^\]]*)\]\s*TJ|\((?P<s>(?:\.|[^\()])*)\)\s*Tj|T\*|Td|TD', txt):
            if m.group('arr') is not None:
                parts = re.findall(r'\((?:\.|[^\()])*\)', m.group('arr'))
                lines.append(''.join(p[1:-1] for p in parts))
            elif m.group('s') is not None:
                lines.append(m.group('s'))
            else:
                lines.append('\n')
    out = ''.join(lines)
    out = out.replace('\(', '(').replace('\)', ')').replace('\\', '\')
    # collapse runs of newlines
    out = re.sub(r'\n{3,}', '\n\n', out)
    return out

for p in sys.argv[1:]:
    print('#' * 30, p, '#' * 30)
    print(extract(p))

