import sys, zlib, re, base64

TXT_OP = re.compile(r'\[(?P<arr>[^\]]*)\]\s*TJ|\((?P<s>(?:\\.|[^\\()])*)\)\s*Tj|T\*|Td|TD|ET')
STR_LIT = re.compile(r'\((?:\\.|[^\\()])*\)')
BS = chr(92)


def unescape(s):
    out = []
    i = 0
    mapping = {'n': chr(10), 'r': chr(13), 't': chr(9), 'b': chr(8), 'f': chr(12)}
    while i < len(s):
        c = s[i]
        if c == BS and i + 1 < len(s):
            nxt = s[i + 1]
            out.append(mapping.get(nxt, nxt))
            i += 2
        else:
            out.append(c)
            i += 1
    return ''.join(out)


def decode_stream(raw):
    data = raw.strip()
    # try ASCII85 first (ReportLab default), then flate
    for attempt in ('a85+flate', 'flate', 'a85'):
        try:
            d = data
            if 'a85' in attempt:
                end = d.find(b'~>')
                body = d[:end] if end >= 0 else d
                d = base64.a85decode(body, adobe=False)
            if 'flate' in attempt:
                d = zlib.decompress(d)
            return d
        except Exception:
            continue
    return None


def extract(path):
    d = open(path, 'rb').read()
    pieces = []
    for m in re.finditer(rb'stream\r?\n', d):
        s = m.end()
        e = d.find(b'endstream', s)
        if e < 0:
            continue
        dec = decode_stream(d[s:e])
        if dec:
            pieces.append(dec)
    lines = []
    for raw in pieces:
        txt = raw.decode('latin-1')
        for m in TXT_OP.finditer(txt):
            if m.group('arr') is not None:
                parts = STR_LIT.findall(m.group('arr'))
                lines.append(''.join(unescape(p[1:-1]) for p in parts))
            elif m.group('s') is not None:
                lines.append(unescape(m.group('s')))
            else:
                lines.append(chr(10))
    out = ''.join(lines)
    out = re.sub(r'\n{3,}', chr(10) + chr(10), out)
    return out


for p in sys.argv[1:]:
    print('#' * 25, p, '#' * 25)
    print(extract(p))

