    e=cby[cid]['expect']
    resp=r['response']
    status_ok = (resp['status'] in e.get('statusAnyOf',[])) if 'statusAnyOf' in e else (resp['status']==e.get('status'))
    if 'httpAnyOf' in e:
        status_ok = r['http'] in e['httpAnyOf'] or resp['status'] in e.get('orStatusAnyOf',[])
    r['triage']={'classification':'HARNESS BUG (my expectation, not a defect) - corrected after review',
